"""GENERATED by tools/make_satwfcga.py from dsa_satwfc.py: the fused DSA decode layer with the attention block's
Sinkhorn inside it (dsa_satwfc's kernel statement for statement) and its selection split across the context-parallel row
groups (form W): each rank's P1 is dsa_sel2gc's classed selection over its row group's rows only, at a quarter layout
(EngineConfig.dsa_rowsplit_layout, "B:naxqa+nbxqb"), and S2 a world all_gather of every rank's lists, so every rank still
merges and attends all B rows with the row group's lists. Measured on trn2 at 24 decode rows: the selection's cost a DSA
layer falls with the rows each rank scores (a quarter of them); the merge, the attend and every output are the classed
form's bit for bit. dsa_satwf.satwf routes a call here when takes() holds. Do not edit; regenerate."""

from __future__ import annotations

import zlib

import torch

from . import dsa_sat as SAT
from . import dsa_satwf as SATWF
from . import ffn_half as FH
from . import mhc_front as MF
from . import mhc_split as MS
from . import dsa_sel2gc as _SLGC
from . import shell as SH

# the Sinkhorn's pieces (1 .. 3: one after each collective's issue)
CKP = 3

try:  # the Neuron venv
    import nki
    import nki.collectives as ncc
    import nki.isa as nisa
    import nki.language as nl
except ImportError:
    nki = None

# -- the kernel source
if nki is not None:
    from .cc_tail import LP, POISON_OUT, POISON_RX, TP, _dma, _tail_body, _tail_weights

    from .dsa_sa import _attend, _rows_i32, _sel2, _snd_write
    from .dsa_sel2gc import _sel2gc
    from .dsa_sat import _snd_write_hbm
    from .dsa_sel_s2 import _s2_payload
    from .dsa_shell import F32, I32, VE, _sb
    from .cc_world import _dma_static, ar_world_alloc, ar_world_back, ar_world_close, ar_world_issue, ar_world_zero1
    from .dsa_satwf import _cp_groups
    from .ffn_half_shared import ffn_half_body

    def _sk_tile(comb_p, B: int, hc: int, eps: float, skf: int):
        """The attention block's Sinkhorn tile from mhc_front's c [B, hc hc]: skf 1 front_body's padded [B, hc + 1,
        hc + 1], its eps row and column a memset as there, c (fp32) by DMA into the inner hc x hc; skf 0 [B, hc, hc]."""
        if skf:
            cpa = _sb((B, hc + 1, hc + 1))
            nisa.memset(dst=cpa, value=eps)
            _dma_static(dst=cpa[:, 0:hc, 0:hc], src=comb_p.ap(pattern=[[hc * hc, B], [hc, hc], [1, hc]], offset=0))
        else:
            cpa = _sb((B, hc, hc))
            _dma_static(dst=cpa, src=comb_p.ap(pattern=[[hc * hc, B], [hc, hc], [1, hc]], offset=0))
        return cpa

    def _sk_piece(cpa, comb_i, hc: int, iters: int, eps: float, skf: int, ckp: int, j: int):
        """Piece j of ckp of the 2 iters - 1 half-rounds (mhc_split.chunk_bounds' split, in a form the parser takes):
        sinkhorn_body's, on cpa in place; the piece reaching the end writes comb_i. Pieces past the last are empty."""
        n_half = 2 * iters - 1
        step = (n_half + ckp - 1) // ckp
        lo = j * step
        hi = lo + step
        if hi > n_half:
            hi = n_half
        if lo < n_half:
            MS.sinkhorn_body(cpa, comb_i, hc, iters, eps, skf, lo, hi)

    def _rcw(na: int, qa: int, nb: int, qb: int):
        """Form W's quarter layout, NG per slot: na slots of qa then nb of qb (built with appends: the parser's form)."""
        ngs = []
        for s in range(na):
            ngs.append(qa)
        for s in range(nb):
            ngs.append(qb)
        return ngs

    def _w_onehot(rank, B: int, A: int):
        """[B, A] fp32: (a == rank) 1.0 / 0.0 on every row (dsa_sel_s2._s2_payload's one-hot)."""
        RKB = _sb((B, 1))
        _dma_static(dst=RKB, src=rank.ap(pattern=[[0, B], [1, 1]], offset=0))
        ai = _sb((B, A), I32)
        nisa.iota(dst=ai, pattern=[[1, A]], offset=0, channel_multiplier=0)
        af = _sb((B, A))
        nisa.tensor_copy(dst=af, src=ai, engine=VE)
        OH = _sb((B, A))
        nisa.tensor_scalar(dst=OH, data=af, op0=nl.equal, operand0=RKB, engine=VE)
        return OH

    def _s2_send_ag(out, xs, Bg: int, keep: int):
        """S2's send: xs [Bg, 3 keep] := this rank's [lval | cpool | rows] (out [3, Bg, keep]) + 0.0, through one
        partition-0 tile filled by DMA (three column blocks), the + 0.0 on the vector engine (the all-reduce's sign of
        zero; every other value unchanged). Every SBUF tile here is partition-0 based and filled by DMA only: a tile
        filled by memset and then DMAs into partition slices at nonzero offsets came out right on the device only at
        partition offset 0 (the simulator had it bitwise)."""
        X = _sb((Bg, 3 * keep))
        for part in range(3):
            _dma_static(dst=X[:, part * keep:(part + 1) * keep], src=out.ap(pattern=[[keep, Bg], [1, keep]], offset=part * Bg * keep))
        X0 = _sb((Bg, 3 * keep))
        nisa.tensor_scalar(dst=X0, data=X, op0=nl.add, operand0=0.0, engine=VE)
        _dma_static(dst=xs, src=X0)

    def _ag_block(G, dst, blk: int, A: int, B: int, Bg: int, keep: int, na: int, nb: int):
        """dst [A, B, keep] := column block blk of the gathered rows G [world Bg, 3 keep] (rank g A + a's row j at G row
        (g A + a) Bg + j), row group g's runs at their batch rows (ra = na g, rb = na RG + nb g), one 4-D HBM -> HBM DMA
        a run over (a, g, j, keep)."""
        ngr = B // (na + nb)  # the row groups
        W3 = 3 * keep
        nisa.dma_copy(dst=dst.ap(pattern=[[B * keep, A], [na * keep, ngr], [keep, na], [1, keep]], offset=0),
                      src=G.ap(pattern=[[Bg * W3, A], [A * Bg * W3, ngr], [W3, na], [1, keep]], offset=blk * keep))
        nisa.dma_copy(dst=dst.ap(pattern=[[B * keep, A], [nb * keep, ngr], [keep, nb], [1, keep]], offset=na * ngr * keep),
                      src=G.ap(pattern=[[Bg * W3, A], [A * Bg * W3, ngr], [W3, nb], [1, keep]], offset=na * W3 + blk * keep))

    def _rows_g(S, rank, B: int, keep: int, A: int, RS):
        """RS [B, keep] int32: slot rank's pool rows from the rows block S [A B, keep] ([A, B] order), as the sum over the
        A slots of slot a's rows times (a == rank): finite integers, every other term an exact zero, so slot rank's
        values."""
        OH = _w_onehot(rank, B, A)
        acc = _sb((B, keep))
        nisa.memset(dst=acc, value=0.0)
        for a in range(A):
            Ra = _sb((B, keep))
            _dma_static(dst=Ra, src=S.ap(pattern=[[keep, B], [1, keep]], offset=a * B * keep))
            Ta = _sb((B, keep))
            nisa.tensor_scalar(dst=Ta, data=Ra, op0=nl.multiply, operand0=OH[:, a:a + 1], engine=VE)
            nisa.tensor_tensor(dst=acc, data1=acc, data2=Ta, op=nl.add, engine=VE)
        RI = _sb((B, keep), I32)
        nisa.tensor_copy(dst=RI, src=acc, engine=VE)
        _dma_static(dst=RS, src=RI)

    @nki.jit
    def dsa_satwfcga_kernel(qT, wb, pkc, ppg, cand, identb, rank, table, pos, q_lat, kc, w_uv_p, o_p, ident, S,
                               post_p, comb_p, fnb, base, fscale, pnorm, bb, bf, fwb, keep: int, A: int, nbits2: int,
                               rbits2: int, world: int, nbits: int, rbits: int, kp: int, ns: int, lkp: int, la: int,
                               scale: float, fp8: int, rev: int, hc: int, iters: int, eps: float, rms_eps: float,
                               sig: int, skf: int, Is: int, K: int, rsc: float, group: int, ring: int, limit: float,
                               rsp: int, o_rt: int, o_gu: int, o_dn: int, o_rb: int, fin: int, dge: int = 0,
                               nr: int = 4, qr: int = 4, pf: int = 2, ts: int = 0, il: int = 1, sb: int = 1,
                               st: int = 1, ss: int = 1, tl: int = 1, fo: int = 1, fq: int = 1, so: int = 1,
                               wu: int = 1, nf: int = 1, ev: int = 1, pn: int = 0, dbg: int = 0, fz: int = 0,
                               wl: int = 0, po: int = 1, ob: int = 0, sh: int = 0, rp: int = 1, pw: int = 0,
                               yb: int = 0, pq: int = 0, cs: int = 0, ckp: int = 3, ra: int = 0, na: int = 0,
                               rb: int = 0, nb: int = 0, qa: int = 0, qb: int = 0):
        """dsa_satwf_kernel's arguments, comb_p mhc_front's c [T, hc hc] in comb's place, and ckp the Sinkhorn's
        pieces (1 .. 3), and form W's static runs: this row group's na rows from slot ra (class qa) and nb from rb
        (class qb). Its outputs, then RSW."""
        Bg = cand.shape[0]  # form W: P1's rows (this row group's)
        _, B, H, R = q_lat.shape  # the batch (every row the attend and the tail see)
        assert fz == 1 and Bg == na + nb and ra + na <= rb and rb + nb <= B, "form W: fz 1 and the group's two runs"
        nh = H // A
        dv = w_uv_p.shape[2]
        Fd = nh * dv
        HID = o_p.shape[1] // (Fd // TP) * 512
        RT, FT, NCH = R // TP, Fd // TP, HID // 512
        Cn = R + LP
        BF = nl.bfloat16
        npg = nl.num_programs(axes=0) if nl.program_ndim() != 0 else 1
        pid = nl.program_id(axis=0) if npg > 1 else 0
        # every buffer allocated in both programs before anything depends on the program id (so it sits at the same
        # address in both traces)
        gv = nl.ndarray((A, B, keep), dtype=F32, buffer=nl.shared_hbm)
        gc = nl.ndarray((A, B, keep), dtype=F32, buffer=nl.shared_hbm)
        if fz:  # cc_world's fenced shape, a shared send / receive buffer a program (a barrier on private HBM is
            # untested in any form)
            s2s0 = nl.ndarray((Bg, 3 * keep), dtype=F32, buffer=nl.shared_hbm)  # each program's send, its rank's own rows
            s2s1 = nl.ndarray((Bg, 3 * keep), dtype=F32, buffer=nl.shared_hbm)
            s2d0 = nl.ndarray((world * Bg, 3 * keep), dtype=F32, buffer=nl.shared_hbm)  # every rank's rows, rank order
            s2d1 = nl.ndarray((world * Bg, 3 * keep), dtype=F32, buffer=nl.shared_hbm)
            s2g = nl.ndarray((A * B, keep), dtype=F32, buffer=nl.shared_hbm)  # the rows block, [A, B] order (program 0's)
            s2src, s2dst = (s2s0, s2d0) if pid == 0 else (s2s1, s2d1)
        else:
            s2src = nl.ndarray((A * B, 3 * keep), dtype=F32, buffer=nl.private_hbm)
            s2dst = nl.ndarray((A * B, 3 * keep), dtype=F32, buffer=nl.private_hbm)
        SND = nl.ndarray((H * B, Cn), dtype=F32, buffer=nl.shared_hbm)  # internal: the all_to_all's send buffer
        RCV0 = nl.ndarray((H * B, Cn), dtype=F32, buffer=nl.shared_hbm)  # internal: each program's receive buffer
        RCV1 = nl.ndarray((H * B, Cn), dtype=F32, buffer=nl.shared_hbm)
        RS = nl.ndarray((B, keep), dtype=I32, buffer=nl.private_hbm)
        # program 0's slot-rank rows of the gathered lists, RETURNED: a kernel output is one buffer in both programs,
        # where internal shared HBM scratch past the first is a per-program copy (program 1 would read its own,
        # never-written one)
        RSW = nl.ndarray((B, keep), dtype=I32, buffer=nl.shared_hbm)
        Y, S0, S1, Z1 = ar_world_alloc(B, HID, BF)  # the world sum's buffers (cc_world's), internal
        Yp = nl.ndarray((npg, B, HID), dtype=BF, buffer=nl.shared_hbm)  # the FFN half's input: [Y, zeros ..]
        o_out = nl.ndarray((nh, B, R), dtype=BF, buffer=nl.shared_hbm)  # the combine's o
        comb_i = nl.ndarray((B, hc * hc), dtype=F32, buffer=nl.private_hbm)  # this program's attention-block comb
        if not wl:  # wl 0: the tail's weights and identity at entry, held through the section
            wuv_all = nl.ndarray((TP, nh * RT, dv), dtype=BF, buffer=nl.sbuf)
            wo_all = nl.ndarray((TP, NCH * FT, 512), dtype=BF, buffer=nl.sbuf)
            if pid == 0:  # program 0 consumes; dge none, off sel2's queues
                _tail_weights(w_uv_p, o_p, wuv_all, wo_all, nh, RT, dv, NCH, FT)
        ar_world_zero1(S1, B, HID, pid)  # program 1's zeros, early, off program 0's critical path
        if pid != 0:  # Yp's zero slots, program 1, early (ffn_half.decode's padding of a DSA layer's one slot)
            yz = _sb((B, 512), BF)
            nisa.memset(dst=yz, value=0.0)
            for g in range(1, npg):
                for c in range(NCH):
                    _dma_static(dst=Yp.ap(pattern=[[HID, B], [1, 512]], offset=g * B * HID + c * 512), src=yz)
        if not wl:
            idt = nl.ndarray((B, B), dtype=BF, buffer=nl.sbuf)
            _dma(dst=idt, src=ident)
        # sel2 (form W: dsa_sel2gc's classed selection over this row group's rows, at the quarter layout)
        out = _sel2gc(qT, wb, pkc, ppg, cand, identb, rank, keep, A, nbits2, rbits2, rev, dge, nr, qr, pf, cs,
                      0, _rcw(na, qa, nb, qb))
        # S2: every rank's lists by a world all_gather; program 0 writes gv / gc and the rows block
        assert world == A * (B // (na + nb)) and ra == na * (rb - na * (world // A)) // nb, \
            "form W: RG = world / A row groups, w_slots' runs"
        _s2_send_ag(out, s2src, Bg, keep)  # the rank's own rows, + 0.0
        if fz and npg > 1:  # both programs' payload writes land before the collective reads them
            nisa.core_barrier(data=s2s0, cores=(0, 1))
            nisa.core_barrier(data=s2s1, cores=(0, 1))
        ncc.all_gather(srcs=[s2src], dsts=[s2dst], replica_group=_cp_groups(world, world), collective_dim=0)  # the world, rank order
        cpa = _sk_tile(comb_p, B, hc, eps, skf)  # the attention block's Sinkhorn: its tile, then piece 0 under S2
        _sk_piece(cpa, comb_i, hc, iters, eps, skf, ckp, 0)
        if fz and npg > 1:  # program 0's gathered rows land before its DMA reads them
            nisa.core_barrier(data=s2d0, cores=(0, 1))
            nisa.core_barrier(data=s2d1, cores=(0, 1))  # program 1's (never read) land too: one in flight
        if pid == 0:  # gv / gc / the rows block from the gathered rows, every group's two runs
            _ag_block(s2dst, gv, 0, A, B, Bg, keep, na, nb)
            _ag_block(s2dst, gc, 1, A, B, Bg, keep, na, nb)
            _ag_block(s2dst, s2g, 2, A, B, Bg, keep, na, nb)
        if npg > 1:  # the rows block lands before program 0's loads read it (a DMA write then read of one tensor)
            nisa.core_barrier(data=s2g, cores=(0, 1))
        if pid == 0:  # program 0 reads its gathered rows (only it reads a collective's destination) into RSW
            _rows_g(s2g, rank, B, keep, A, RSW)
        if npg > 1:
            nisa.core_barrier(data=gv, cores=(0, 1))
            nisa.core_barrier(data=gc, cores=(0, 1))
            nisa.core_barrier(data=RSW, cores=(0, 1))  # program 0's RSW lands before either program reads it (the attend)
        # P3 / P3f: the attend with the fold
        if wl:  # wl 1: the tail's weights and identity after the attend, no tile held across the section (an early
            # device run read entry-held tiles wrong after it [inference])
            wuv_all = nl.ndarray((TP, nh * RT, dv), dtype=BF, buffer=nl.sbuf)
            wo_all = nl.ndarray((TP, NCH * FT, 512), dtype=BF, buffer=nl.sbuf)
            if pid == 0:
                _tail_weights(w_uv_p, o_p, wuv_all, wo_all, nh, RT, dv, NCH, FT)
            idt = nl.ndarray((B, B), dtype=BF, buffer=nl.sbuf)
            _dma(dst=idt, src=ident)
        o, lse, srows, sbias, over = _attend(gv, gc, RSW, table, pos, rank, q_lat, kc, keep, A, kp, ns, nbits, rbits,
                                             lkp, la, scale, fp8, rev, ts, il, sb, st, ss, tl, fo, fq)
        if ob and npg > 1:  # ob 1: the attend's HBM outputs o / lse land before _snd_write's DMA reads them back
            nisa.core_barrier(data=o, cores=(0, 1))  # (a same-tensor DMA write then read: rows t >= B / 2 read wrong)
            nisa.core_barrier(data=lse, cores=(0, 1))
        # the receive buffers poisoned (each program its own, cc_tail's form), then the send rows
        if rp:  # rp 0: no poison of the receive buffers (an SBUF-sourced write the a2a's write may overtake)
            pzr = _sb((H * B, Cn))
            nisa.memset(dst=pzr, value=POISON_RX)
            _dma(dst=RCV0 if pid == 0 else RCV1, src=pzr)
            if fz and npg > 1:  # the poison lands before the all_to_all writes the receive buffers
                nisa.core_barrier(data=RCV0, cores=(0, 1))
                nisa.core_barrier(data=RCV1, cores=(0, 1))
        split = npg == 2 and B >= 2
        k_lo, k_hi = (0, B) if not split else ((0, (B + 1) // 2) if pid == 0 else ((B + 1) // 2, B))
        rows = []
        if pw:  # pw 1 (served): program 0 writes every row, program 1 none
            if pid == 0:
                for t in range(B):
                    rows.append(t)
        elif split or pid == 0:
            for t in range(k_lo, k_hi):
                rows.append(t)
        if sh or pw:  # sh 1: each program's rows HBM -> HBM into SND (no SBUF-sourced write for the other to consume)
            _snd_write_hbm(o, lse, SND, B, H, R, rows)
        else:
            _snd_write(o, lse, SND, B, H, R, rows)
        if pn == 1:  # a check: NaN in these rows' padding columns r+1 .., which no receiver reads
            pnn = _sb((H, LP - 1))
            nisa.memset(dst=pnn, value=float("nan"))
            for t in rows:
                _dma(dst=SND.ap(pattern=[[B * Cn, H], [1, LP - 1]], offset=t * Cn + R + 1), src=pnn)
        if pn == 2:  # its positive control: NaN in row 0's lse column r (live), every head; row 0 must move, no other
            pnl = _sb((H, 1))
            nisa.memset(dst=pnl, value=float("nan"))
            for t in rows:
                if t == 0:
                    _dma(dst=SND.ap(pattern=[[B * Cn, H], [1, 1]], offset=R), src=pnl)
        if npg > 1:
            nisa.core_barrier(data=SND, cores=(0, 1))
        ncc.all_to_all(srcs=[SND], dsts=[RCV0 if pid == 0 else RCV1], replica_group=_cp_groups(world, A),
                       collective_dim=0)
        _sk_piece(cpa, comb_i, hc, iters, eps, skf, ckp, 1)  # piece 1 under the all_to_all
        if fz and npg > 1:  # the received rows land before the tail's DMA reads them
            nisa.core_barrier(data=RCV0, cores=(0, 1))
            nisa.core_barrier(data=RCV1, cores=(0, 1))
        if pid == 0:  # the tail, program 0 alone (only it consumes collective results), its o_proj into the world sum's send buffer S0
            if po:  # po 0: no poison writes (the tail writes every element; a same-program DMA write-after-write)
                pzy = _sb((B, 512), BF)
                nisa.memset(dst=pzy, value=POISON_OUT)
                for j in range(nh):
                    _dma(dst=o_out.ap(pattern=[[R, B], [1, R]], offset=j * B * R), src=pzy[:, 0:R])
            _tail_body(RCV0, wuv_all, wo_all, idt, S0, o_out, B, A, nh, R, dv, HID, so, wu, nf, ev, 1)
        ar_world_issue(Y, S0, S1, Z1, world, pid, npg=npg, fence=fz)  # cc_world's fence under fz
        _sk_piece(cpa, comb_i, hc, iters, eps, skf, ckp, 2)  # piece 2 under the world sum
        if (npg == 1 or B % npg == 0) and not yb:  # yb 1: program 0 copies Y (program 1 never reads Y)
            ar_world_back(Y, Yp, B, HID, pid, npg)  # into slot 0 (its rows 0 .. B - 1), then a barrier on Yp
        else:  # a row count the programs can't split (T 1 at grid 2): program 0 copies Y after the sum lands
            ar_world_close(Y, npg)
            if pid == 0:
                yb = _sb((B, HID), BF)
                _dma(dst=yb, src=Y)
                _dma(dst=Yp.ap(pattern=[[HID, B], [1, HID]], offset=0), src=yb)
            if npg > 1:
                nisa.core_barrier(data=Yp, cores=(0, 1))
        if fz and npg > 1:  # program 1's sum (Z1), never read, also lands before anything else issues
            nisa.core_barrier(data=Z1, cores=(0, 1))
        if npg > 1:
            nisa.core_barrier(data=o_out, cores=(0, 1))
        # the FFN half (ffn_half_shared's body, the decode FFN half kernel's statements), both programs
        fh = ffn_half_body(S, post_p, comb_i, Yp, fnb, base, fscale, pnorm, bb, bf, fwb, hc, iters, eps, rms_eps, sig,
                           skf, Is, K, rsc, group, ring, limit, rsp, o_rt, o_gu, o_dn, o_rb, dbg, fin)
        return (gv, gc, out, o, lse, srows, sbias, over, Yp, o_out, RSW) + tuple(fh)
else:
    dsa_satwfcga_kernel = None




def _rev() -> int:
    """This module's kernel source with the revisions of what it runs (the section and the FFN half through
    dsa_satwf.REV, the Sinkhorn's, the classed selection's), one ordered hash: the compile-cache key does not hash NKI
    kernel source. A call adds its batch size's layout terms."""
    import hashlib

    t = open(__file__).read()
    a = t.index("# -- the kernel source")
    b = t.index("    dsa_satwfcga_kernel = None", a)
    return int(hashlib.sha256(repr((t[a:b], SATWF.REV, MS.REV_K, _SLGC.REVGC_BASE)).encode()).hexdigest()[:8], 16)


REV = _rev()


def satwf(*args, rowgroup: int, S, post_a, comb_a, blobs: dict, w_blob, ffn: dict, grid: int | None = None,
          ckp: int | None = None, **kw):
    """dsa_satwf.satwf's call with the attention block's comb_a a mhc_front.PendingComb (c, the Sinkhorn's input), in
    form W for the rank's row group `rowgroup`: the same arguments and returns."""
    if not isinstance(comb_a, MF.PendingComb):
        raise TypeError("dsa_satwfc.satwf takes the attention block's comb as mhc_front.PendingComb")
    ckp = CKP if ckp is None else int(ckp)
    if not 1 <= ckp <= 3:
        raise ValueError(f"ckp {ckp}: 1, 2 or 3 (one piece after each collective's issue)")
    if kw.get("fz") != 1:
        raise ValueError("dsa_satwfcga: form W needs the fenced S2 (fz 1, the fused layer's form)")
    q = args[0]
    sargs, kern, grid, T, H, R = SAT.sat_args(*args, grid=grid, _kernel=dsa_satwfcga_kernel, _rev=REV, **kw)
    if _SLGC.CW:  # the candidate bias built in the kernel from nloc (args[4]); sat_args' [T, P] mask is dead code
        sargs["cand"] = args[4].float().reshape(-1, 1).contiguous()
    sargs.update(_w_args(sargs, q, T, rowgroup))  # P1 on the row group's rows
    sargs["rev"] = int(sargs["rev"]) ^ _SLGC.layout_crc(T) ^ _W_CRC.get(T, 0)  # the batch's own layouts key it
    _, hc, Hm = S.shape
    fargs = FH.run(S, (post_a, comb_a.c, S.new_zeros(1)), blobs, w_blob, grid=grid, build_only=True, **ffn)
    fargs.pop("Yp")  # built in the kernel
    fargs.pop("rev")  # REV carries FS.REV (through SATWF.REV)
    # the FFN half's stream mix with its rows split (shell.MIX_ROW_SPLIT) is a different kernel: its term, as run()'s
    sargs["rev"] = int(sargs["rev"]) ^ SH.mix_rev_term()
    fargs["fscale"], fargs["fwb"] = fargs.pop("scale"), fargs.pop("wb")
    clash = set(fargs) & set(sargs)
    if clash:
        raise ValueError(f"satwfc: the FFN half's arguments {sorted(clash)} are the section's names")
    from libtorch_neuronx_lite.nki.nki_hop import wrap_nki

    outs = wrap_nki(kern)[grid](**sargs, **fargs, ckp=ckp)
    gv, gc, o3, o, ls, _, _, ov, Yp, o_out = outs[:10]
    Sn, post, comb, rp, sp = outs[11:16]  # RSW at 10
    return ((gv, gc, o3[0], o3[1], o3[2].to(torch.int32), o.view(T, H, R), ls.view(T, H), ov.amax(dim=1), Yp, o_out,
             Sn.view(T, hc, Hm), post, comb.view(T, hc, hc), FH.to_rows(rp), sp) + tuple(outs[16:]))



def parse_w(spec: str) -> dict:
    """A form-W layout spec, "B:naxqa+nbxqb[,B:..]" (e.g. "24:2x24+4x6") -> {B: (na, qa, nb, qb)}: a row group's two runs
    of slots (na slots of class qa, nb of qb; each count even, slots alternating between the LNC programs as sel2gc's).
    A batch size appears once: a repeat would silently replace the first layout."""
    out = {}
    for part in filter(None, (p.strip() for p in spec.split(","))):
        b, cls = part.split(":")
        if int(b) in out:
            raise ValueError(f"form W layout {part!r}: batch size {int(b)} has a layout already")
        runs = [tuple(int(v) for v in c.split("x")) for c in cls.split("+")]
        if len(runs) != 2 or any(n % 2 or n < 2 or g < 1 for n, g in runs):
            raise ValueError(f"form W layout {part!r}: two runs NxG of even N >= 2")
        out[int(b)] = (runs[0][0], runs[0][1], runs[1][0], runs[1][1])
    return out


RG = 4  # the row groups (attention TP / the context-parallel degree: 32 / 8)
# {B: (na, qa, nb, qb)} and each batch size's own revision term: set_layouts sets them (the engine's set_decode_routes on
# every rank, from EngineConfig.dsa_rowsplit_layout, after dsa_sel2gc's layouts). Empty: no call takes form W.
W_LAYOUTS: dict = {}
_W_CRC: dict = {}


def w_slots(T: int, g: int, lay: dict | None = None):
    """(ra, na, rb, nb): row group g's rows of a T-row batch under the layout: na rows from na g (the first na RG slots,
    the full layout's widest), nb rows from na RG + nb g (the rest)."""
    na, _, nb, _ = (W_LAYOUTS if lay is None else lay)[T]
    if T != RG * (na + nb):
        raise ValueError(f"form W layout {T}: {RG} groups of {na} + {nb} rows is not {T}")
    return na * g, na, na * RG + nb * g, nb


def check_layouts(lay: dict, full_layouts: dict) -> None:
    """Every group's rows fit its quarter classes under the full row-class layout (slot by slot), and the quarter's
    widest class is the full layout's (sel2gc's NPg == 128 max NG, the same page bucket). Raises otherwise."""
    for T, (na, qa, nb, qb) in lay.items():
        full = full_layouts.get(T)
        if full is None:
            raise ValueError(f"form W layout {T}: no row-class layout at B {T}")
        if max(qa, qb) != max(full):
            raise ValueError(f"form W layout {T}: widest class {max(qa, qb)} is not the full layout's {max(full)}")
        for g in range(RG):
            ra, _, rb, _ = w_slots(T, g, lay)
            if any(full[s] > qa for s in range(ra, ra + na)) or any(full[s] > qb for s in range(rb, rb + nb)):
                raise ValueError(f"form W layout {T}: group {g}'s slots don't fit ({na}x{qa}+{nb}x{qb} vs {full})")


def set_layouts(spec: str) -> None:
    """W_LAYOUTS and their revision terms from a layout spec (parse_w), checked against dsa_sel2gc's layouts; "" clears."""
    global W_LAYOUTS, _W_CRC
    lay = parse_w(spec)
    check_layouts(lay, _SLGC.LAYOUTS)
    W_LAYOUTS = lay
    _W_CRC = {int(b): zlib.crc32(repr(("form W", int(b), w)).encode()) for b, w in lay.items()}


def takes(T: int, table: torch.Tensor, comb_a, world: int, A: int) -> bool:
    """Whether a fused decode call of T rows takes form W: a quarter layout at T, the classed selection would take
    (dsa_sel2gc.takes: the runner's guard and the layout's page bucket), the attention block's comb a PendingComb (this
    module's form), and the world RG row groups of A ranks."""
    return T in W_LAYOUTS and _SLGC.takes(T, table) and isinstance(comb_a, MF.PendingComb) and world == RG * A


def _w_args(sargs: dict, q: torch.Tensor, T: int, g: int) -> dict:
    """P1's arguments on row group g's rows (qT's columns, wb / cand rows, ppg classed at the quarter layout over those
    rows' table rows at the full page width) and the kernel's static run arguments."""
    ra, na, rb, nb = w_slots(T, g)
    _, qa, _, qb = W_LAYOUTS[T]
    Hi = q.shape[1]
    rows = lambda x: torch.cat([x[ra:ra + na], x[rb:rb + nb]], dim=0).contiguous()  # noqa: E731 (two static runs: slices, no index tensor in the trace)
    qT = sargs["qT"]
    ngs = (qa,) * na + (qb,) * nb
    return dict(qT=torch.cat([qT[:, ra * Hi:(ra + na) * Hi], qT[:, rb * Hi:(rb + nb) * Hi]], dim=1).contiguous(), wb=rows(sargs["wb"]),
                cand=rows(sargs["cand"]), ppg=_SLGC.classed_ppg(rows(sargs["table"]), ngs), ra=ra, na=na, rb=rb, nb=nb, qa=qa, qb=qb)
